$(() => {
  const 家前缀 = '三号楼1002';
  const 拖鞋 = '棉拖鞋';
  // 兜底鞋从初始衣柜实际存在的鞋里按优先级选取，保证写进变量的鞋衣柜里真有
  const 出门鞋优先 = ['蓝色帆布鞋', '白色运动鞋', '黑色乐福鞋'];
  // 常见旧称/俗称 → 衣柜条目名
  const 鞋别名: Record<string, string> = { 小白鞋: '白色运动鞋', 帆布鞋: '蓝色帆布鞋' };
  // 仅当用户明确表达与不变量冲突的意图时才让位；「换鞋出门」这类同向指令不算反向指令
  const 鞋袜反向指令 = /(光脚|赤脚|不穿|拖鞋)/;
  const 钥匙反向指令 = /(不带钥匙|别带钥匙|不用带钥匙|钥匙留在家里|忘带钥匙)/;

  function 找正文鞋(正文: string, 衣柜: Record<string, unknown>): string | undefined {
    const 直配 = 出门鞋优先.find(k => !!衣柜[k] && 正文.includes(k));
    if (直配) return 直配;
    const 别名 = Object.entries(鞋别名).find(([alias]) => 正文.includes(alias) && !!衣柜[鞋别名[alias]]);
    return 别名 ? 鞋别名[别名[0]] : undefined;
  }

  function 规范化鞋名(值: string, 衣柜: Record<string, unknown>): string | undefined {
    if (出门鞋优先.some(k => !!衣柜[k] && 值 === k)) return undefined;
    const 直配 = 出门鞋优先.find(k => !!衣柜[k] && 值.includes(k));
    if (直配) return 直配;
    const 别名 = Object.entries(鞋别名).find(([alias]) => 值.includes(alias) && !!衣柜[鞋别名[alias]]);
    return 别名 ? 鞋别名[别名[0]] : undefined;
  }

  waitGlobalInitialized('Mvu').then(() => {
    eventOn(Mvu.events.VARIABLE_UPDATE_ENDED, (新变量, 旧变量) => {
      const 最新 = getChatMessages(-1)[0];
      if (!最新 || 最新.role !== 'assistant' || 最新.message_id === 0) return;

      const 位置 = 新变量?.stat_data?.位置?.地点 as string | undefined;
      const 脚部 = 新变量?.stat_data?.穿着?.脚部 as string | undefined;
      const 携带 = 新变量?.stat_data?.当前携带 as string[] | undefined;
      if (typeof 位置 !== 'string' || typeof 脚部 !== 'string' || !Array.isArray(携带)) return;

      const 在家 = 位置.startsWith(家前缀);
      const 衣柜 = (新变量?.stat_data?.['$衣柜'] ?? {}) as Record<string, unknown>;
      const 玩家楼层 = getChatMessages(-2).filter(m => m.role === 'user').at(-1);
      const 玩家消息 = 玩家楼层?.message ?? '';

      // ===== 不变量一/二：棉拖鞋不出家门、在家穿棉拖鞋 =====
      const 旧脚部 = 旧变量?.stat_data?.穿着?.脚部 as string | undefined;
      const 脚部已由AI结算 = 旧脚部 !== undefined && 脚部 !== 旧脚部;
      if (!脚部已由AI结算 && !(玩家消息 && 鞋袜反向指令.test(玩家消息))) {
        if (!在家) {
          if (脚部.includes('拖鞋')) {
            const 最终鞋 =
              找正文鞋(最新.message, 衣柜) ??
              规范化鞋名(脚部, 衣柜) ??
              出门鞋优先.find(k => !!衣柜[k]) ??
              '蓝色帆布鞋';
            _.set(新变量.stat_data, '穿着.脚部', 最终鞋);
          } else {
            // 鞋名与衣柜不符的规范化（如「白色帆布鞋」→「蓝色帆布鞋」）
            const 规范 = 规范化鞋名(脚部, 衣柜) ?? 找正文鞋(最新.message, 衣柜);
            if (规范) _.set(新变量.stat_data, '穿着.脚部', 规范);
          }
        } else if (脚部 !== '无' && !脚部.includes('拖鞋')) {
          _.set(新变量.stat_data, '穿着.脚部', 拖鞋);
        }
      }

      // ===== 不变量三：人不在家则必须带着家门钥匙 =====
      if (!在家 && !携带.includes('家门钥匙') && !(玩家消息 && 钥匙反向指令.test(玩家消息))) {
        _.set(新变量.stat_data, '当前携带', [...携带, '家门钥匙']);
      }
    });
  });
});
